INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES (0, 11, 103231, 0, 0.5, 8, "こうして大勢のみなさまと過ごすお正月\n賑やかで最高ですわね！", 0, 0, 310001, 310);
