INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES (0, 11, 100911, 0, 0.5, 8, "疼く……疼くぞ！\n我が魔眼が新たなる年を祝えと……！", 0, 0, 311006, 311);
INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES ("", 91, 311006, "", "", "", "", "", "", 311007, 311);
