INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES (0, 11, 101611, 0, 0.5, 8, "見て見てミサキっち！\nあそこの料理すっごく美味しそう！", 0, 0, 312005, 312);
INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES ("", 3, 101611, "", "", 1, "nop_talk_surprise_kira", 0.2, "", 312006, 312);
INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES ("", 91, 312005, "", "", "", "", "", "", 312007, 312);
INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES ("", 3, 101611, "", "", 1, "nop_idle_surprise_kira", 0.2, 1, 312008, 312);
INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES (0, 11, 105011, 0, 0.5, 8, "えー？　でもあれって野菜じゃない？\n別に、大人のレディだから\n食べられないわけじゃないけど？", 0, 0, 312009, 312);
INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES ("", 3, 105011, "", "", 1, "nop_talk_sad", 0.2, "", 312010, 312);
