INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES (0, 11, 105331, 0, 0.5, 8, "立派な新年会ではないか。\n我々もこの場に相応しく\n振る舞わなければな！", 0, 0, 313001, 313);
INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES (0.2, 3, 105331, "nop_13_monica_talk_doya_loop", "", 0, "nop_13_monica_talk_doya", 0.2, 1, 313002, 313);
